async (page) => {
  // 공격 작전 그룹의 '코치에게' 버튼 클릭
  const attackGroup = page.locator('dialog:has-text("경기 운영 설정")').locator('role=group[name="공격 작전"]');
  await attackGroup.locator('button:has-text("코치에게")').click();

  // 모달 내부의 '저장' 버튼 클릭
  const modalSaveBtn = page.locator('dialog:has-text("경기 운영 설정")').locator('button:has-text("저장")');
  await modalSaveBtn.click();

  // 경기 시작 버튼 클릭
  await page.locator('button:has-text("경기 시작")').click();
}
